import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"22、【贲】 离下艮上","description":"横渠易说 - 22、【贲】 离下艮上","frontmatter":{"title":"22、【贲】 离下艮上","description":"横渠易说 - 22、【贲】 离下艮上"},"headers":[],"relativePath":"zh/classics/hengqu/024.md","filePath":"zh/classics/hengqu/024.md"}'),t={name:"zh/classics/hengqu/024.md"};function l(n,a,s,c,d,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_22、【贲】-离下艮上" tabindex="-1">22、【贲】 离下艮上 <a class="header-anchor" href="#_22、【贲】-离下艮上" aria-label="Permalink to “22、【贲】 离下艮上”">​</a></h1><h3 id="彖曰-贲亨-柔来而文刚-故亨。分刚上而文柔-故小利有攸往-天文也-文明以止-人文也。观乎天文以察时变-观乎人文以化成天下。" tabindex="-1">彖曰：贲亨，柔来而文刚，故亨。分刚上而文柔，故小利有攸往，天文也；文明以止，人文也。观乎天文以察时变，观乎人文以化成天下。 <a class="header-anchor" href="#彖曰-贲亨-柔来而文刚-故亨。分刚上而文柔-故小利有攸往-天文也-文明以止-人文也。观乎天文以察时变-观乎人文以化成天下。" aria-label="Permalink to “彖曰：贲亨，柔来而文刚，故亨。分刚上而文柔，故小利有攸往，天文也；文明以止，人文也。观乎天文以察时变，观乎人文以化成天下。”">​</a></h3><h3 id="象曰-山下有火-贲-君子以明庶政-无敢折狱。" tabindex="-1">象曰：山下有火，贲，君子以明庶政，无敢折狱。 <a class="header-anchor" href="#象曰-山下有火-贲-君子以明庶政-无敢折狱。" aria-label="Permalink to “象曰：山下有火，贲，君子以明庶政，无敢折狱。”">​</a></h3><p>无敢折狱者，明不兼于下，民未孚也，故止可明政以示民耳。</p><h3 id="初九-贲其趾-舍车而徒。-象曰-舍车而徒-义弗乘也。" tabindex="-1">初九，贲其趾，舍车而徒。 象曰：“舍车而徒”，义弗乘也。 <a class="header-anchor" href="#初九-贲其趾-舍车而徒。-象曰-舍车而徒-义弗乘也。" aria-label="Permalink to “初九，贲其趾，舍车而徒。 象曰：“舍车而徒”，义弗乘也。”">​</a></h3><p>文明之德，以贵居贱，修饰于下，故曰“贲其趾”；义非苟进，故曰“舍车而徒”。六一，贲其须。 象曰：“贲其须”，与上兴也。 贲其须，起意在上也。</p><h3 id="九三-贲如濡如-永贞吉。-象曰-永贞之吉-终莫之陵也。" tabindex="-1">九三，贲如濡如，永贞吉。 象曰：永贞之吉，终莫之陵也。 <a class="header-anchor" href="#九三-贲如濡如-永贞吉。-象曰-永贞之吉-终莫之陵也。" aria-label="Permalink to “九三，贲如濡如，永贞吉。 象曰：永贞之吉，终莫之陵也。”">​</a></h3><p>上下皆柔，无物陵犯，然不可邪妄自肆，故永贞然后终保无悔。</p><h3 id="六四-贲如皤如-白马翰如-匪寇婚媾。-象曰-六四当位-疑也。-匪寇婚媾-终无尤也。" tabindex="-1">六四，贲如皤如，白马翰如，匪寇婚媾。 象曰：六四当位，疑也。“匪寇婚媾”，终无尤也。 <a class="header-anchor" href="#六四-贲如皤如-白马翰如-匪寇婚媾。-象曰-六四当位-疑也。-匪寇婚媾-终无尤也。" aria-label="Permalink to “六四，贲如皤如，白马翰如，匪寇婚媾。 象曰：六四当位，疑也。“匪寇婚媾”，终无尤也。”">​</a></h3><p>以阴居阴，性为艮止，故志坚行洁，终无尤累。</p><h3 id="六五-贲于丘园-束帛戋戋-吝终吉。-象曰-六五之吉-有喜也。" tabindex="-1">六五，贲于丘园，束帛戋戋，吝终吉。 象曰：六五之吉，有喜也。 <a class="header-anchor" href="#六五-贲于丘园-束帛戋戋-吝终吉。-象曰-六五之吉-有喜也。" aria-label="Permalink to “六五，贲于丘园，束帛戋戋，吝终吉。 象曰：六五之吉，有喜也。”">​</a></h3><p>阴阳相固，物所阜生，柔中之德比于上九。上九敦素，因可恃而致富，虽为悔吝，然获其吉也。 其道上行，故曰“丘园”。悔一作隘。</p><h3 id="上九-白贲-无咎。-象曰-白贲无咎-上得志也。" tabindex="-1">上九，白贲，无咎。 象曰：“白贲无咎”，上得志也。 <a class="header-anchor" href="#上九-白贲-无咎。-象曰-白贲无咎-上得志也。" aria-label="Permalink to “上九，白贲，无咎。 象曰：“白贲无咎”，上得志也。”">​</a></h3><p>上而居高，洁无所累，为物所贵，故曰“上得志也”。上一作止。</p>',14)])])}const m=e(t,[["render",l]]);export{_ as __pageData,m as default};
